create extension if not exists pgcrypto;
create type public.workspace_role as enum ('owner','admin','member','viewer');
create table public.workspaces (id uuid primary key default gen_random_uuid(),name text not null check(char_length(name) between 2 and 120),slug text not null unique check(slug ~ '^[a-z0-9-]+$'),created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now());
create table public.workspace_members (workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role public.workspace_role not null default 'member',created_at timestamptz not null default now(),primary key(workspace_id,user_id));
create table public.contacts (id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,created_by uuid not null references auth.users(id) on delete restrict,full_name text not null check(char_length(full_name) between 1 and 200),email text,company text,job_title text,source text,notes text,stage text not null default 'new' check(stage in ('new','contacted','engaged','qualified','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.activities (id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,actor_id uuid not null references auth.users(id) on delete restrict,contact_id uuid references public.contacts(id) on delete set null,kind text not null check(kind in ('note','email_draft','status_change','search')),summary text not null,created_at timestamptz not null default now());
create index contacts_workspace_created_idx on public.contacts(workspace_id,created_at desc);
create index activities_workspace_created_idx on public.activities(workspace_id,created_at desc);
create index workspace_members_user_idx on public.workspace_members(user_id,workspace_id);
create function public.is_workspace_member(target_workspace uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.workspace_members wm where wm.workspace_id=target_workspace and wm.user_id=(select auth.uid())); $$;
create function public.has_workspace_role(target_workspace uuid,allowed public.workspace_role[]) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.workspace_members wm where wm.workspace_id=target_workspace and wm.user_id=(select auth.uid()) and wm.role=any(allowed)); $$;
alter table public.workspaces enable row level security;
alter table public.workspace_members enable row level security;
alter table public.contacts enable row level security;
alter table public.activities enable row level security;
create policy "Members view workspaces" on public.workspaces for select to authenticated using(public.is_workspace_member(id));
create policy "Users create own workspaces" on public.workspaces for insert to authenticated with check(created_by=(select auth.uid()));
create policy "Admins update workspaces" on public.workspaces for update to authenticated using(public.has_workspace_role(id,array['owner','admin']::public.workspace_role[])) with check(public.has_workspace_role(id,array['owner','admin']::public.workspace_role[]));
create policy "Members view membership" on public.workspace_members for select to authenticated using(public.is_workspace_member(workspace_id));
create policy "Admins manage membership" on public.workspace_members for all to authenticated using(public.has_workspace_role(workspace_id,array['owner','admin']::public.workspace_role[])) with check(public.has_workspace_role(workspace_id,array['owner','admin']::public.workspace_role[]));
create policy "Members view contacts" on public.contacts for select to authenticated using(public.is_workspace_member(workspace_id));
create policy "Editors insert contacts" on public.contacts for insert to authenticated with check(created_by=(select auth.uid()) and public.has_workspace_role(workspace_id,array['owner','admin','member']::public.workspace_role[]));
create policy "Editors update contacts" on public.contacts for update to authenticated using(public.has_workspace_role(workspace_id,array['owner','admin','member']::public.workspace_role[])) with check(public.has_workspace_role(workspace_id,array['owner','admin','member']::public.workspace_role[]));
create policy "Admins delete contacts" on public.contacts for delete to authenticated using(public.has_workspace_role(workspace_id,array['owner','admin']::public.workspace_role[]));
create policy "Members view activities" on public.activities for select to authenticated using(public.is_workspace_member(workspace_id));
create policy "Editors add activities" on public.activities for insert to authenticated with check(actor_id=(select auth.uid()) and public.has_workspace_role(workspace_id,array['owner','admin','member']::public.workspace_role[]));
create function public.create_workspace(workspace_name text,workspace_slug text) returns uuid language plpgsql security definer set search_path='' as $$ declare new_id uuid; begin if auth.uid() is null then raise exception 'Authentication required'; end if; insert into public.workspaces(name,slug,created_by) values(workspace_name,workspace_slug,auth.uid()) returning id into new_id; insert into public.workspace_members(workspace_id,user_id,role) values(new_id,auth.uid(),'owner'); return new_id; end; $$;
grant execute on function public.create_workspace(text,text) to authenticated;
